{"command": "cd /tmp/sv-96081ac82d5d4da5bee1628d53fb7e93/advanced-multi-complexity && dotnet package list --format json 2>&1 | cat > after-cpm-packages.json && python3 -c "
import json

baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

print('CHANGES:')
changes = False
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes = True
        proj, fw, pkg = k
        print(f'  {proj} ({fw}) | {pkg} | {bv or \"(none)\"} -> {av or \"(none)\"}')
if not changes:
    print('  (none)')

print()
print('UNCHANGED:')
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv == av:
        proj, fw, pkg = k
        print(f'  {proj} ({fw}) | {pkg} | {av}')
